def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    n = len(sites)
    if n == 0 or not bonds:
        return 0.0
    props = s.get('element_properties') or {}
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    adjacency = [[] for i in range(n)]
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        image = bond.get('image')
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] <= 0.0 or occ[j] <= 0.0 or image is None or len(image) != 3:
            continue
        if d <= 1.2 * (radii[i] + radii[j]):
            adjacency[i] += [(j, (image[0], image[1], image[2]))]
    offsets = [None for i in range(n)]
    queue = [0 for i in range(n)]
    finite_weight = 0.0
    for root in range(n):
        if occ[root] <= 0.0 or offsets[root] is not None:
            continue
        offsets[root] = (0, 0, 0)
        queue[0] = root
        count = 1
        component_weight = 0.0
        periodic = False
        for head in range(n):
            if head >= count:
                break
            i = queue[head]
            component_weight += occ[i]
            position = offsets[i]
            for j, image in adjacency[i]:
                target = (position[0] + image[0], position[1] + image[1], position[2] + image[2])
                if offsets[j] is None:
                    offsets[j] = target
                    queue[count] = j
                    count += 1
                elif offsets[j] != target:
                    periodic = True
        if not periodic:
            finite_weight += component_weight
    return finite_weight / max(sum(occ), 1e-12)

