def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    nearest = [0.0 for i in range(n)]
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and occ[i] > 0.0 and occ[j] > 0.0 and 0.0 < d <= 6.0:
            if nearest[i] == 0.0 or d < nearest[i]:
                nearest[i] = d
    outer = [6.0 for i in range(n)]
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and occ[j] > 0.0 and nearest[i] > 0.0:
            if 1.25 * nearest[i] < d <= 6.0 and d < outer[i]:
                outer[i] = d
    total = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] > 0.0 and nearest[i] > 0.0:
            boundary = 1.25 * nearest[i]
            total += occ[i] * log(max(1.0, outer[i] / boundary))
            weight += occ[i]
    return total / max(weight, 1e-12)
